/* ChartPulse — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

:root {
  --bg-primary: #0f0f0f;
  --bg-secondary: #1a1a2e;
  --bg-card: #16162a;
  --bg-card-hover: #1e1e3a;
  --bg-surface: #121225;
  --bg-input: #1c1c35;
  --border-color: #2a2a4a;
  --border-subtle: #222240;
  --text-primary: #e8e8f0;
  --text-secondary: #9090b0;
  --text-muted: #6060a0;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1e50e0;
  --accent-teal: #26a69a;
  --positive: #26a69a;
  --positive-bg: rgba(38, 166, 154, 0.12);
  --negative: #F7525F;
  --negative-bg: rgba(247, 82, 95, 0.12);
  --gold: #f0b90b;
  --platinum: #a0a0c0;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent-blue); text-decoration: none; }
a:hover { color: var(--accent-blue-hover); }

img { max-width: 100%; display: block; }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 3px; }

/* Navigation */
.nav {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  position: sticky; top: 0; z-index: 100;
}
.nav-inner {
  max-width: 1440px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 24px; height: 56px;
}
.nav-logo {
  font-size: 20px; font-weight: 800; color: var(--text-primary);
  display: flex; align-items: center; gap: 8px;
}
.nav-logo .logo-icon {
  width: 28px; height: 28px; background: var(--accent-blue);
  border-radius: 6px; display: flex; align-items: center; justify-content: center;
  font-size: 14px; color: #fff;
}
.nav-links { display: flex; gap: 4px; }
.nav-links a {
  color: var(--text-secondary); padding: 8px 14px; border-radius: var(--radius-sm);
  font-size: 13px; font-weight: 500; transition: all 0.2s;
}
.nav-links a:hover, .nav-links a.active {
  color: var(--text-primary); background: rgba(255,255,255,0.05);
}
.nav-actions { display: flex; align-items: center; gap: 10px; }
.nav-search {
  background: var(--bg-input); border: 1px solid var(--border-color);
  border-radius: var(--radius-sm); padding: 6px 12px; color: var(--text-primary);
  font-size: 13px; width: 200px; outline: none;
}
.nav-search:focus { border-color: var(--accent-blue); }

/* Buttons */
.btn {
  padding: 8px 18px; border-radius: var(--radius-sm); font-size: 13px;
  font-weight: 600; cursor: pointer; border: none; transition: all 0.2s;
  display: inline-flex; align-items: center; gap: 6px;
}
.btn-primary { background: var(--accent-blue); color: #fff; }
.btn-primary:hover { background: var(--accent-blue-hover); }
.btn-secondary { background: transparent; color: var(--text-secondary); border: 1px solid var(--border-color); }
.btn-secondary:hover { border-color: var(--text-secondary); color: var(--text-primary); }
.btn-sm { padding: 5px 12px; font-size: 12px; }

/* Containers */
.container { max-width: 1440px; margin: 0 auto; padding: 0 24px; }
.section { padding: 32px 0; }
.section-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 20px;
}
.section-title { font-size: 20px; font-weight: 700; }
.section-subtitle { font-size: 13px; color: var(--text-secondary); }

/* Cards */
.card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-md); padding: 16px; transition: all 0.2s;
}
.card:hover { border-color: var(--border-subtle); background: var(--bg-card-hover); }

/* Tabs */
.tabs { display: flex; gap: 2px; background: var(--bg-surface); border-radius: var(--radius-sm); padding: 2px; }
.tab {
  padding: 6px 14px; border-radius: var(--radius-sm); font-size: 12px;
  font-weight: 500; cursor: pointer; color: var(--text-secondary);
  background: transparent; border: none; transition: all 0.2s; white-space: nowrap;
}
.tab:hover { color: var(--text-primary); }
.tab.active { background: var(--accent-blue); color: #fff; }

/* Badge */
.badge {
  display: inline-flex; align-items: center; padding: 2px 8px;
  border-radius: 3px; font-size: 11px; font-weight: 600;
}
.badge-positive { background: var(--positive-bg); color: var(--positive); }
.badge-negative { background: var(--negative-bg); color: var(--negative); }
.badge-neutral { background: rgba(144,144,176,0.12); color: var(--text-secondary); }
.badge-platinum { background: rgba(160,160,192,0.12); color: var(--platinum); font-size: 10px; text-transform: uppercase; letter-spacing: 0.5px; }
.badge-gold { background: rgba(240,185,11,0.12); color: var(--gold); font-size: 10px; text-transform: uppercase; letter-spacing: 0.5px; }

/* Tables */
.data-table { width: 100%; border-collapse: collapse; }
.data-table th {
  text-align: left; padding: 8px 12px; font-size: 11px; font-weight: 600;
  color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border-color);
}
.data-table td {
  padding: 10px 12px; font-size: 13px; border-bottom: 1px solid var(--border-subtle);
}
.data-table tr:hover td { background: rgba(255,255,255,0.02); }
.data-table .ticker { font-weight: 600; color: var(--accent-blue); }
.data-table .price { font-weight: 600; font-variant-numeric: tabular-nums; }
.data-table .positive { color: var(--positive); }
.data-table .negative { color: var(--negative); }

/* Market Bar */
.market-bar {
  background: var(--bg-secondary); border-bottom: 1px solid var(--border-color);
  overflow-x: auto; white-space: nowrap;
}
.market-bar-inner {
  display: flex; gap: 24px; padding: 8px 24px; max-width: 1440px; margin: 0 auto;
}
.market-bar-item {
  display: flex; align-items: center; gap: 8px; font-size: 12px;
}
.market-bar-item .name { color: var(--text-secondary); font-weight: 500; }
.market-bar-item .value { font-weight: 600; font-variant-numeric: tabular-nums; }

/* Sparkline SVG placeholder */
.sparkline {
  width: 80px; height: 30px; display: inline-block; vertical-align: middle;
}

/* Grid Layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
.grid-6 { display: grid; grid-template-columns: repeat(6, 1fr); gap: 12px; }

/* Footer */
.footer {
  background: var(--bg-secondary); border-top: 1px solid var(--border-color);
  padding: 48px 0 24px;
}
.footer-grid {
  display: grid; grid-template-columns: repeat(6, 1fr); gap: 24px;
  max-width: 1440px; margin: 0 auto; padding: 0 24px;
}
.footer-col h4 { font-size: 13px; font-weight: 700; margin-bottom: 12px; color: var(--text-primary); }
.footer-col a {
  display: block; font-size: 12px; color: var(--text-secondary);
  padding: 3px 0; transition: color 0.2s;
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  max-width: 1440px; margin: 0 auto; padding: 24px 24px 0;
  border-top: 1px solid var(--border-color); margin-top: 32px;
  display: flex; justify-content: space-between; align-items: center;
  font-size: 12px; color: var(--text-muted);
}

/* Utility */
.text-positive { color: var(--positive) !important; }
.text-negative { color: var(--negative) !important; }
.text-muted { color: var(--text-secondary); }
.text-right { text-align: right; }
.text-center { text-align: center; }
.fw-600 { font-weight: 600; }
.fw-700 { font-weight: 700; }
.fs-11 { font-size: 11px; }
.fs-12 { font-size: 12px; }
.fs-13 { font-size: 13px; }
.fs-16 { font-size: 16px; }
.fs-20 { font-size: 20px; }
.fs-24 { font-size: 24px; }
.fs-32 { font-size: 32px; }
.fs-48 { font-size: 48px; }
.mt-8 { margin-top: 8px; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mb-8 { margin-bottom: 8px; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.gap-8 { gap: 8px; }
.gap-12 { gap: 12px; }
.gap-16 { gap: 16px; }
.flex { display: flex; }
.flex-center { display: flex; align-items: center; }
.flex-between { display: flex; align-items: center; justify-content: space-between; }
.flex-col { display: flex; flex-direction: column; }
.flex-wrap { flex-wrap: wrap; }
.flex-1 { flex: 1; }
.inline-flex { display: inline-flex; align-items: center; }

/* Star rating */
.stars { color: var(--gold); font-size: 12px; letter-spacing: 1px; }

/* Responsive */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-6 { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .grid-6 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .nav-links { display: none; }
  .nav-search { width: 140px; }
  .market-bar-inner { padding: 8px 16px; }
  .container { padding: 0 16px; }
}

/* Chart page specific */
.chart-layout {
  display: grid; grid-template-columns: 280px 1fr 320px;
  height: calc(100vh - 56px); overflow: hidden;
}
.chart-sidebar {
  background: var(--bg-secondary); border-right: 1px solid var(--border-color);
  overflow-y: auto;
}
.chart-main { display: flex; flex-direction: column; overflow: hidden; }
.chart-detail-panel {
  background: var(--bg-secondary); border-left: 1px solid var(--border-color);
  overflow-y: auto; padding: 16px;
}

/* Watchlist */
.watchlist-header {
  padding: 12px 16px; font-size: 14px; font-weight: 700;
  border-bottom: 1px solid var(--border-color);
  display: flex; align-items: center; justify-content: space-between;
}
.watchlist-group-header {
  padding: 8px 16px; font-size: 12px; font-weight: 600;
  color: var(--text-secondary); background: var(--bg-surface);
  cursor: pointer; display: flex; align-items: center; justify-content: space-between;
  border-bottom: 1px solid var(--border-subtle); user-select: none;
}
.watchlist-group-header:hover { background: var(--bg-card); }
.watchlist-group-header .arrow { transition: transform 0.2s; font-size: 10px; }
.watchlist-group-header.collapsed .arrow { transform: rotate(-90deg); }
.watchlist-group { border-bottom: 1px solid var(--border-subtle); }
.watchlist-item {
  display: grid; grid-template-columns: 1fr auto auto auto;
  padding: 6px 16px; font-size: 12px; gap: 12px; align-items: center;
  border-bottom: 1px solid rgba(42,42,74,0.3); cursor: pointer;
}
.watchlist-item:hover { background: rgba(255,255,255,0.02); }
.watchlist-item .symbol { font-weight: 600; color: var(--text-primary); }
.watchlist-group-content { overflow: hidden; transition: max-height 0.3s ease; }
.watchlist-group-content.collapsed { max-height: 0 !important; overflow: hidden; }

/* Chart toolbar */
.chart-toolbar {
  display: flex; align-items: center; gap: 8px; padding: 8px 16px;
  border-bottom: 1px solid var(--border-color); background: var(--bg-secondary);
  flex-wrap: wrap;
}
.toolbar-group { display: flex; align-items: center; gap: 4px; }
.toolbar-btn {
  padding: 4px 8px; font-size: 12px; background: transparent; border: 1px solid transparent;
  color: var(--text-secondary); border-radius: var(--radius-sm); cursor: pointer;
}
.toolbar-btn:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }
.toolbar-btn.active { color: var(--accent-blue); border-color: var(--accent-blue); }
.toolbar-divider { width: 1px; height: 20px; background: var(--border-color); margin: 0 4px; }
.toolbar-symbol {
  font-weight: 700; font-size: 15px; color: var(--text-primary); margin-right: 8px;
}

/* Candlestick chart area */
.chart-area {
  flex: 1; background: var(--bg-primary); position: relative; overflow: hidden;
  display: flex; align-items: center; justify-content: center;
}
.chart-canvas { width: 100%; height: 100%; }

/* Stock detail */
.detail-ticker { font-size: 18px; font-weight: 700; }
.detail-company { font-size: 12px; color: var(--text-secondary); }
.detail-price { font-size: 28px; font-weight: 700; margin: 8px 0 4px; }
.detail-change { font-size: 14px; font-weight: 600; }
.detail-section { margin-top: 16px; padding-top: 16px; border-top: 1px solid var(--border-color); }
.detail-row {
  display: flex; justify-content: space-between; padding: 4px 0;
  font-size: 12px;
}
.detail-row .label { color: var(--text-secondary); }
.detail-row .value { font-weight: 600; font-variant-numeric: tabular-nums; }
.detail-headline {
  background: var(--bg-surface); border-radius: var(--radius-sm);
  padding: 10px; margin-top: 12px; font-size: 12px; line-height: 1.5;
  color: var(--text-secondary); border-left: 3px solid var(--accent-blue);
}

/* Ideas page */
.idea-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-md); overflow: hidden; transition: all 0.2s;
}
.idea-card:hover { border-color: var(--accent-blue); transform: translateY(-2px); }
.idea-chart-preview {
  height: 180px; background: var(--bg-surface);
  display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
}
.idea-chart-preview .overlay-badge {
  position: absolute; top: 8px; left: 8px;
}
.idea-body { padding: 14px; }
.idea-title { font-size: 14px; font-weight: 600; margin-bottom: 6px; line-height: 1.4; }
.idea-meta { display: flex; align-items: center; gap: 10px; font-size: 11px; color: var(--text-secondary); }
.idea-meta .author { font-weight: 600; color: var(--accent-blue); }
.idea-stats { display: flex; gap: 12px; margin-top: 8px; font-size: 11px; color: var(--text-muted); }

/* Broker card */
.broker-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-md); padding: 20px; display: flex;
  align-items: center; gap: 20px; transition: all 0.2s;
}
.broker-card:hover { border-color: var(--accent-blue); }
.broker-logo {
  width: 60px; height: 60px; background: var(--bg-surface);
  border-radius: var(--radius-md); display: flex; align-items: center;
  justify-content: center; font-weight: 700; font-size: 11px;
  color: var(--text-secondary); flex-shrink: 0;
}
.broker-info { flex: 1; }
.broker-name { font-size: 16px; font-weight: 700; margin-bottom: 4px; }
.broker-rating { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
.broker-stats { display: flex; gap: 20px; font-size: 12px; color: var(--text-secondary); }
.broker-promo {
  background: var(--positive-bg); color: var(--positive); padding: 6px 12px;
  border-radius: var(--radius-sm); font-size: 12px; font-weight: 600;
  white-space: nowrap;
}

/* Pagination */
.pagination { display: flex; justify-content: center; gap: 4px; margin-top: 32px; }
.page-btn {
  width: 36px; height: 36px; display: flex; align-items: center; justify-content: center;
  background: var(--bg-card); border: 1px solid var(--border-color); border-radius: var(--radius-sm);
  color: var(--text-secondary); font-size: 13px; cursor: pointer;
}
.page-btn:hover { border-color: var(--accent-blue); color: var(--text-primary); }
.page-btn.active { background: var(--accent-blue); border-color: var(--accent-blue); color: #fff; }

/* Hero */
.hero {
  padding: 80px 0; text-align: center;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}
.hero h1 { font-size: 48px; font-weight: 800; line-height: 1.15; max-width: 720px; margin: 0 auto 16px; }
.hero p { font-size: 18px; color: var(--text-secondary); max-width: 600px; margin: 0 auto 32px; line-height: 1.6; }
.hero-actions { display: flex; gap: 12px; justify-content: center; }

/* Stats banner */
.stats-banner {
  background: linear-gradient(135deg, var(--bg-secondary) 0%, #1a1a40 100%);
  border: 1px solid var(--border-color); border-radius: var(--radius-lg);
  padding: 40px; display: flex; justify-content: center; gap: 80px;
  margin: 40px 0;
}
.stat-item { text-align: center; }
.stat-value { font-size: 36px; font-weight: 800; color: var(--accent-blue); }
.stat-label { font-size: 13px; color: var(--text-secondary); margin-top: 4px; }

/* Toggle switch */
.toggle-wrapper { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--text-secondary); }
.toggle {
  width: 36px; height: 20px; background: var(--border-color); border-radius: 10px;
  position: relative; cursor: pointer; transition: background 0.2s;
}
.toggle.active { background: var(--accent-blue); }
.toggle::after {
  content: ''; position: absolute; width: 16px; height: 16px; background: #fff;
  border-radius: 50%; top: 2px; left: 2px; transition: transform 0.2s;
}
.toggle.active::after { transform: translateX(16px); }

/* Markets page yield curve */
.yield-curve {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-md); padding: 20px; height: 200px;
  display: flex; align-items: flex-end; gap: 16px; justify-content: center;
}
.yield-bar {
  display: flex; flex-direction: column; align-items: center; gap: 4px;
}
.yield-bar-fill {
  width: 40px; background: var(--accent-blue); border-radius: 3px 3px 0 0;
  min-height: 10px; transition: height 0.3s;
}
.yield-bar-label { font-size: 10px; color: var(--text-muted); }
.yield-bar-value { font-size: 11px; font-weight: 600; color: var(--text-primary); }

@media (max-width: 1024px) {
  .chart-layout { grid-template-columns: 1fr; }
  .chart-sidebar, .chart-detail-panel { display: none; }
  .hero h1 { font-size: 32px; }
  .stats-banner { flex-direction: column; gap: 24px; padding: 24px; }
}

