}
.badge-positive { background: var(--positive-bg); color: var(--positive); }
.badge-negative { background: var(--negative-bg); color: var(--negative); }
.badge-neutral { background: rgba(144,144,176,0.12); color: var(--text-secondary); }
.badge-platinum { background: rgba(160,160,192,0.12); color: var(--platinum); font-size: 10px; text-transform: uppercase; letter-spacing: 0.5px; }
.badge-gold { background: rgba(240,185,11,0.12); color: var(--gold); font-size: 10px; text-transform: uppercase; letter-spacing: 0.5px; }

