  border-bottom: 1px solid var(--border-color);
}
.data-table td {
  padding: 10px 12px; font-size: 13px; border-bottom: 1px solid var(--border-subtle);
}
.data-table tr:hover td { background: rgba(255,255,255,0.02); }
.data-table .ticker { font-weight: 600; color: var(--accent-blue); }
.data-table .price { font-weight: 600; font-variant-numeric: tabular-nums; }
.data-table .positive { color: var(--positive); }
.data-table .negative { color: var(--negative); }

/* Market Bar */
.market-bar {
  background: var(--bg-secondary); border-bottom: 1px solid var(--border-color);
  overflow-x: auto; white-space: nowrap;
}
.market-bar-inner {
  display: flex; gap: 24px; padding: 8px 24px; max-width: 1440px; margin: 0 auto;
}
