  color: var(--text-secondary); border-left: 3px solid var(--accent-blue);
}

/* Ideas page */
.idea-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-md); overflow: hidden; transition: all 0.2s;
}
.idea-card:hover { border-color: var(--accent-blue); transform: translateY(-2px); }
.idea-chart-preview {
