/* ChartPulse — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

:root {
  --bg-primary: #0f0f0f;
  --bg-secondary: #1a1a2e;
  --bg-card: #16162a;
  --bg-card-hover: #1e1e3a;
  --bg-surface: #121225;
  --bg-input: #1c1c35;
  --border-color: #2a2a4a;
  --border-subtle: #222240;
  --text-primary: #e8e8f0;
  --text-secondary: #9090b0;
  --text-muted: #6060a0;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1e50e0;
  --accent-teal: #26a69a;
  --positive: #26a69a;
  --positive-bg: rgba(38, 166, 154, 0.12);
  --negative: #F7525F;
  --negative-bg: rgba(247, 82, 95, 0.12);
  --gold: #f0b90b;
  --platinum: #a0a0c0;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent-blue); text-decoration: none; }
a:hover { color: var(--accent-blue-hover); }

img { max-width: 100%; display: block; }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 3px; }

/* Navigation */
.nav {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  position: sticky; top: 0; z-index: 100;
}
.nav-inner {
  max-width: 1440px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 24px; height: 56px;
}
.nav-logo {
  font-size: 20px; font-weight: 800; color: var(--text-primary);
  display: flex; align-items: center; gap: 8px;
}
.nav-logo .logo-icon {
  width: 28px; height: 28px; background: var(--accent-blue);
  border-radius: 6px; display: flex; align-items: center; justify-content: center;
  font-size: 14px; color: #fff;
}
.nav-links { display: flex; gap: 4px; }
.nav-links a {
  color: var(--text-secondary); padding: 8px 14px; border-radius: var(--radius-sm);
  font-size: 13px; font-weight: 500; transition: all 0.2s;
}
.nav-links a:hover, .nav-links a.active {
  color: var(--text-primary); background: rgba(255,255,255,0.05);
}
.nav-actions { display: flex; align-items: center; gap: 10px; }
.nav-search {
  background: var(--bg-input); border: 1px solid var(--border-color);
  border-radius: var(--radius-sm); padding: 6px 12px; color: var(--text-primary);
  font-size: 13px; width: 200px; outline: none;
}
.nav-search:focus { border-color: var(--accent-blue); }

/* Buttons */
.btn {
  padding: 8px 18px; border-radius: var(--radius-sm); font-size: 13px;
  font-weight: 600; cursor: pointer; border: none; transition: all 0.2s;
  display: inline-flex; align-items: center; gap: 6px;
}
.btn-primary { background: var(--accent-blue); color: #fff; }
.btn-primary:hover { background: var(--accent-blue-hover); }
.btn-secondary { background: transparent; color: var(--text-secondary); border: 1px solid var(--border-color); }
.btn-secondary:hover { border-color: var(--text-secondary); color: var(--text-primary); }
.btn-sm { padding: 5px 12px; font-size: 12px; }

/* Containers */
.container { max-width: 1440px; margin: 0 auto; padding: 0 24px; }
.section { padding: 32px 0; }
.section-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 20px;
}
.section-title { font-size: 20px; font-weight: 700; }
.section-subtitle { font-size: 13px; color: var(--text-secondary); }

/* Cards */
.card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-md); padding: 16px; transition: all 0.2s;
}
.card:hover { border-color: var(--border-subtle); background: var(--bg-card-hover); }

/* Tabs */
.tabs { display: flex; gap: 2px; background: var(--bg-surface); border-radius: var(--radius-sm); padding: 2px; }
.tab {
  padding: 6px 14px; border-radius: var(--radius-sm); font-size: 12px;
  font-weight: 500; cursor: pointer; color: var(--text-secondary);
  background: transparent; border: none; transition: all 0.2s; white-space: nowrap;
}
.tab:hover { color: var(--text-primary); }
.tab.active { background: var(--accent-blue); color: #fff; }

/* Badge */
.badge {
  display: inline-flex; align-items: center; padding: 2px 8px;
  border-radius: 3px; font-size: 11px; font-weight: 600;
}
.badge-positive { background: var(--positive-bg); color: var(--positive); }
