}

function selectSymbol(symbol) {
  document.querySelector('.toolbar-symbol').textContent = symbol;
  document.querySelectorAll('.watchlist-item').forEach(item => {
    item.style.background = '';
  });
  event.currentTarget.style.background = 'rgba(41,98,255,0.08)';
  drawChart();
}

// Timeframe toggle
document.querySelectorAll('.toolbar-group .toolbar-btn[data-tf]').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.toolbar-btn[data-tf]').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    drawChart();
  });
});

// Financials tabs
document.querySelectorAll('#financials-tabs .tab').forEach(tab => {
  tab.addEventListener('click', () => {
    document.querySelectorAll('#financials-tabs .tab').forEach(t => t.classList.remove('active'));
    tab.classList.add('active');
    document.getElementById('financials-annual').style.display = tab.dataset.tab === 'annual' ? 'block' : 'none';
    document.getElementById('financials-quarterly').style.display = tab.dataset.tab === 'quarterly' ? 'block' : 'none';
  });
});

// Candlestick Chart Drawing
function drawChart() {
  const canvas = document.getElementById('candlestick-chart');
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.parentElement.getBoundingClientRect();
  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  canvas.style.width = rect.width + 'px';
  canvas.style.height = rect.height + 'px';
  ctx.scale(dpr, dpr);

  const w = rect.width;
  const h = rect.height;
  const padding = { top: 20, right: 60, bottom: 40, left: 10 };
  const chartW = w - padding.left - padding.right;
  const chartH = h - padding.top - padding.bottom;

  ctx.fillStyle = '#0f0f0f';
  ctx.fillRect(0, 0, w, h);

  // Generate random OHLC data
  const numCandles = 60;
  let price = 263.40;
  const data = [];
  for (let i = 0; i < numCandles; i++) {
    const open = price + (Math.random() - 0.5) * 4;
    const close = open + (Math.random() - 0.48) * 6;
    const high = Math.max(open, close) + Math.random() * 3;
    const low = Math.min(open, close) - Math.random() * 3;
    data.push({ open, close, high, low });
    price = close;
  }

  const allPrices = data.flatMap(d => [d.high, d.low]);
  const minP = Math.min(...allPrices) - 2;
  const maxP = Math.max(...allPrices) + 2;
  const priceRange = maxP - minP;

  const candleW = chartW / numCandles;
  const bodyW = candleW * 0.6;

  const toY = (p) => padding.top + chartH * (1 - (p - minP) / priceRange);

  // Grid lines
  ctx.strokeStyle = '#1a1a2e';
  ctx.lineWidth = 0.5;
  const gridLines = 6;
  for (let i = 0; i <= gridLines; i++) {
    const y = padding.top + (chartH / gridLines) * i;
    ctx.beginPath();
    ctx.moveTo(padding.left, y);
    ctx.lineTo(w - padding.right, y);
    ctx.stroke();

    const priceLabel = maxP - (priceRange / gridLines) * i;
    ctx.fillStyle = '#6060a0';
    ctx.font = '11px Inter, sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText(priceLabel.toFixed(2), w - padding.right + 8, y + 4);
  }

  // Draw candles
  data.forEach((d, i) => {
    const x = padding.left + i * candleW + candleW / 2;
    const bullish = d.close >= d.open;
    const color = bullish ? '#26a69a' : '#F7525F';

    // Wick
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, toY(d.high));
    ctx.lineTo(x, toY(d.low));
    ctx.stroke();

    // Body
    ctx.fillStyle = color;
    const top = toY(Math.max(d.open, d.close));
    const bottom = toY(Math.min(d.open, d.close));
    const bodyH = Math.max(bottom - top, 1);
    ctx.fillRect(x - bodyW / 2, top, bodyW, bodyH);
  });

  // Volume bars
  const volH = 40;
  const volBase = h - padding.bottom;
  data.forEach((d, i) => {
    const x = padding.left + i * candleW + candleW / 2;
    const vol = Math.random() * 0.8 + 0.2;
    const bullish = d.close >= d.open;
    ctx.fillStyle = bullish ? 'rgba(38,166,154,0.3)' : 'rgba(247,82,95,0.3)';
    ctx.fillRect(x - bodyW / 2, volBase - vol * volH, bodyW, vol * volH);
  });

  // Current price line
  const lastPrice = data[data.length - 1].close;
  const lastY = toY(lastPrice);
  ctx.setLineDash([4, 4]);
  ctx.strokeStyle = '#2962FF';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(padding.left, lastY);
  ctx.lineTo(w - padding.right, lastY);
  ctx.stroke();
  ctx.setLineDash([]);

  // Price badge
  ctx.fillStyle = '#2962FF';
  ctx.fillRect(w - padding.right, lastY - 10, 58, 20);
  ctx.fillStyle = '#fff';
  ctx.font = '11px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(lastPrice.toFixed(2), w - padding.right + 29, lastY + 4);
}

window.addEventListener('resize', drawChart);
drawChart();
</script>

